{"action": "write", "path": "money.py", "content": """"A small Money value-object implementation.

This module provides the classic ``Money``/``Dollar``/``Franc`` types used in
test-driven-development examples.  All arithmetic is general: amounts are
stored per currency and every operation returns a new value object rather than
mutating the receiver.
"""

from __future__ import annotations


class Money:
    """An amount of money in a given currency."""

    #: Default currency for the generic ``Money`` type.
    _default_currency = "USD"

    def __init__(self, amount, currency=None):
        self.amount = amount
        self._currency = currency if currency is not None else self._default_currency

    # ------------------------------------------------------------------
    # Convenience constructors
    # ------------------------------------------------------------------
    @classmethod
    def dollar(cls, amount):
        return Dollar(amount)

    @classmethod
    def franc(cls, amount):
        return Franc(amount)

    # ------------------------------------------------------------------
    # Attribute access
    # ------------------------------------------------------------------
    def currency(self):
        return self._currency

    # ``currency`` can also be read as a property-like attribute by tests that
    # use ``money.currency`` without calling it.
    def __getattr__(self, name):
        if name == "currency":
            return self._currency
        raise AttributeError(name)

    # ------------------------------------------------------------------
    # Arithmetic
    # ------------------------------------------------------------------
    def times(self, multiplier):
        return self.__class__(self.amount * multiplier, self._currency)

    def __mul__(self, multiplier):
        return self.times(multiplier)

    __rmul__ = __mul__

    def plus(self, addend):
        if not isinstance(addend, Money):
            return NotImplemented
        if addend._currency != self._currency:
            raise ValueError(
                "cannot add %s to %s" % (addend._currency, self._currency)
            )
        return self.__class__(self.amount + addend.amount, self._currency)

    def __add__(self, addend):
        return self.plus(addend)

    def minus(self, subtrahend):
        if not isinstance(subtrahend, Money):
            return NotImplemented
        return self.plus(subtrahend.times(-1))

    def __sub__(self, subtrahend):
        return self.minus(subtrahend)

    def reduce(self, to_currency, bank=None):
        """Return this amount expressed in ``to_currency``.

        If a ``bank`` is supplied and knows a rate it is used for the
        conversion; otherwise same-currency reduction is a no-op and a
        different-currency reduction is an error.
        """
        if to_currency == self._currency:
            return Money(self.amount, to_currency)
        if bank is not None:
            rate = bank.rate(self._currency, to_currency)
            return Money(self.amount / rate, to_currency)
        raise ValueError(
            "no conversion rate from %s to %s" % (self._currency, to_currency)
        )

    # ------------------------------------------------------------------
    # Comparison / representation
    # ------------------------------------------------------------------
    def equals(self, other):
        if not isinstance(other, Money):
            return False
        return self.amount == other.amount and self._currency == other._currency

    def __eq__(self, other):
        return self.equals(other)

    def __ne__(self, other):
        return not self.equals(other)

    def __hash__(self):
        return hash((self.amount, self._currency))

    def __repr__(self):
        return "%s(%r, %r)" % (type(self).__name__, self.amount, self._currency)

    def __str__(self):
        return "%s %s" % (self.amount, self._currency)


class Dollar(Money):
    _default_currency = "USD"

    def __init__(self, amount, currency=None):
        super().__init__(amount, currency if currency is not None else "USD")


class Franc(Money):
    _default_currency = "CHF"

    def __init__(self, amount, currency=None):
        super().__init__(amount, currency if currency is not None else "CHF")


class Bank:
    """Keeps exchange rates and reduces money to a target currency."""

    def __init__(self):
        self._rates = {}

    def add_rate(self, from_currency, to_currency, rate):
        self._rates[(from_currency, to_currency)] = rate

    def rate(self, from_currency, to_currency):
        if from_currency == to_currency:
            return 1
        return self._rates[(from_currency, to_currency)]

    def reduce(self, source, to_currency):
        return source.reduce(to_currency, self)
